  public static Spec.NumericConstraint.Builder mergeNumericConstraint(
      Spec.NumericConstraint dst, Spec.NumericConstraint src) {
    Spec.NumericConstraint.Builder builder = dst.toBuilder();
    if (dst.getGt() == 0) {
      builder.setGt(src.getGt());
    }
    if (dst.getGe() == 0) {
      builder.setGe(src.getGe());
    }
    if (dst.getLt() == 0) {
      builder.setLt(src.getLt());
    }
    if (dst.getLe() == 0) {
      builder.setLe(src.getLe());
    }
    if (dst.getEq() == 0) {
      builder.setEq(src.getEq());
    }
    if (dst.getNe() == 0) {
      builder.setNe(src.getNe());
    }
    if (dst.getInList().isEmpty()) {
      builder.addAllIn(src.getInList());
    }
    if (dst.getNotInList().isEmpty()) {
      builder.addAllNotIn(src.getNotInList());
    }
    if (dst.getMultipleOf() == 0) {
      builder.setMultipleOf(src.getMultipleOf());
    }
    return builder;
  }

  public static Spec.FloatConstraint.Builder mergeFloatConstraint(
      Spec.FloatConstraint dst, Spec.FloatConstraint src) {
    Spec.FloatConstraint.Builder builder = dst.toBuilder();
    if (dst.getGt() == 0.0) {
      builder.setGt(src.getGt());
    }
    if (dst.getGe() == 0.0) {
      builder.setGe(src.getGe());
    }
    if (dst.getLt() == 0.0) {
      builder.setLt(src.getLt());
    }
    if (dst.getLe() == 0.0) {
      builder.setLe(src.getLe());
    }
    if (dst.getEpsilon() == 0.0) {
      builder.setEpsilon(src.getEpsilon());
    }
    if (dst.getInList().isEmpty()) {
      builder.addAllIn(src.getInList());
    }
    if (dst.getNotInList().isEmpty()) {
      builder.addAllNotIn(src.getNotInList());
    }
    return builder;
  }

