    result.put("PROTO_NUMERIC_CONSTRAINT_GE", String.valueOf(msg.getGe()));
    result.put("PROTO_NUMERIC_CONSTRAINT_LT", String.valueOf(msg.getLt()));
    result.put("PROTO_NUMERIC_CONSTRAINT_LE", String.valueOf(msg.getLe()));
    result.put("PROTO_NUMERIC_CONSTRAINT_EQ", String.valueOf(msg.getEq()));
    result.put("PROTO_NUMERIC_CONSTRAINT_NE", String.valueOf(msg.getNe()));
    if (!msg.getInList().isEmpty()) {
      result.put(
          "PROTO_NUMERIC_CONSTRAINT_IN",
          msg.getInList().stream().map(String::valueOf).collect(Collectors.joining(",")));
    }
    if (!msg.getNotInList().isEmpty()) {
      result.put(
          "PROTO_NUMERIC_CONSTRAINT_NOT_IN",
          msg.getNotInList().stream().map(String::valueOf).collect(Collectors.joining(",")));
    }
    result.put("PROTO_NUMERIC_CONSTRAINT_MULTIPLE_OF", String.valueOf(msg.getMultipleOf()));
    return result;
