  public static Map<String, String> restMethodsToEnvVar(Spec.RestMethods msg) {
    Map<String, String> result = new HashMap<>();
    if (!msg.getMethodsList().isEmpty()) {
      result.put(
          "PROTO_REST_METHODS_METHODS",
          msg.getMethodsList().stream()
              .map(v -> restMethodToString(v))
              .collect(Collectors.joining(",")));
    }
    return result;
  }

  public static Spec.RestMethods.Builder restMethodsFromEnvVar(Map<String, String> env) {
    Spec.RestMethods.Builder builder = Spec.RestMethods.newBuilder();
    String val;
    val = env.get("PROTO_REST_METHODS_METHODS");
    if (val != null && !val.isEmpty()) {
      for (String part : val.split(",")) {
        builder.addAllMethods(java.util.Collections.singletonList(parseRestMethod(part.trim())));
      }
    }
    return builder;
  }
